import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useToast } from '../hooks/useToast';
import {
  Users, MessageSquare, Megaphone,
  ShieldAlert, Settings, LogOut,
  Plus, Search, UserPlus, Send, Layout, Bell, Sparkles, BrainCircuit, ShieldCheck, X,
  AlertTriangle, CheckCircle, TrendingUp, FileText, Paperclip, Camera, Image as ImageIcon
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { messagingAPI, authAPI, notificationAPI, aiAPI, epreuveAPI, academicAPI, coursAPI } from '../services/api';
import { clearSession } from '../utils/authSession';
import { pushBackHandler } from '../utils/backHandler';
import { useViewNavigation } from '../hooks/useViewNavigation';
import DashboardBackButton from './DashboardBackButton';
import FloatingAIAssistant from './FloatingAIAssistant';
import AnimatedBackground from './AnimatedBackground';
import ProfileModal from './ProfileModal';
import AssistanceWidget from './AssistanceWidget';
import MobileMenu from './MobileMenu';
import LogoutConfirmModal from './LogoutConfirmModal';
import '../Dashboard.css';

const DELEGATE_VIEW_LABELS = {
  group: 'Mon Groupe',
  resources: 'Ressources',
  students: 'Étudiants',
  annonces: 'Annonces',
};

const DelegateDashboard = () => {
  const { view, switchView, goBack, canGoBack, getBackLabel } = useViewNavigation('group');
  const { showToast, ToastUI } = useToast();
  const [user, setUser] = useState(null);

  const [groupes, setGroupes] = useState([]);
  const [selectedGroupe, setSelectedGroupe] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showNotifList, setShowNotifList] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  
  // Resources & AI
  const [epreuves, setEpreuves] = useState([]);
  const [matieres, setMatieres] = useState([]);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showAnnonceModal, setShowAnnonceModal] = useState(false);
  const [showIssueModal, setShowIssueModal] = useState(false);
  const [showChat, setShowChat] = useState(false);

  // Bouton RETOUR (Android) : modals puis navigation interne
  useEffect(() => {
    const off = pushBackHandler(() => {
      if (showLogoutConfirm) { setShowLogoutConfirm(false); return true; }
      if (showProfile) { setShowProfile(false); return true; }
      if (showNotifList) { setShowNotifList(false); return true; }
      if (showUploadModal) { setShowUploadModal(false); return true; }
      if (showAnnonceModal) { setShowAnnonceModal(false); return true; }
      if (showIssueModal) { setShowIssueModal(false); return true; }
      if (showChat) { setShowChat(false); return true; }
      if (canGoBack) { goBack(); return true; }
      return false;
    });
    return off;
  }, [canGoBack, showLogoutConfirm, showProfile, showNotifList, showUploadModal, showAnnonceModal, showIssueModal, showChat, goBack]);

  const [question, setQuestion] = useState('');
  const [chatLog, setChatLog] = useState([{ role: 'ai', text: 'Bonjour Délégué ! Comment puis-je aider votre promotion aujourd\'hui ?' }]);
  const [chatLoading, setChatLoading] = useState(false);
  // Pièces jointes IA
  const [aiFile, setAiFile] = useState(null);
  const [aiFileName, setAiFileName] = useState('');
  const aiFileInputRef = useRef(null);
  const aiCameraInputRef = useRef(null);
  const handleAiFileChange = (e) => {
    const f = e.target.files?.[0];
    if (!f) return;
    setAiFile(f);
    setAiFileName(f.name);
  };
  
  // Forms
  const [file, setFile] = useState(null);
  const [uploadData, setUploadData] = useState({ 
    identifiant: '', titre: '', annee: 2026, session: 'HARMATTAN', matiereId: '', isPublic: true, prix: 0, docType: 'EPREUVE' 
  });
  const [annonceForm, setAnnonceForm] = useState({ titre: '', message: '' });
  const [issueForm, setIssueForm] = useState({ message: '' });

  const fetchData = useCallback(async () => {
    try {
      const uRes = await authAPI.getProfile();
      setUser(uRes.data);

      if (uRes.data?.universite?.couleur) {
          document.documentElement.style.setProperty('--primary', uRes.data.universite.couleur);
          document.documentElement.style.setProperty('--primary-glow', `${uRes.data.universite.couleur}44`);
      }

      const uid = uRes.data?.id;
      const [gRes, nRes, eRes, mRes] = await Promise.all([
        messagingAPI.getGroupes(),
        uid ? notificationAPI.getMe(uid) : Promise.resolve({ data: [] }),
        epreuveAPI.getAll(),
        academicAPI.getMatieres(),
      ]);
      setGroupes(gRes.data);
      setNotifications(nRes.data);
      setEpreuves(eRes.data);
      setMatieres(mRes.data);
      if (gRes.data.length > 0) handleSelectGroupe(gRes.data[0]);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  }, []);

  const handleSelectGroupe = async (groupe) => {
    setSelectedGroupe(groupe);
    try {
      const res = await messagingAPI.getMessages(groupe.id);
      setMessages(res.data);
    } catch (err) { console.error(err); }
  };

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage || !selectedGroupe) return;
    try {
      await messagingAPI.sendMessage(selectedGroupe.id, newMessage);
      setNewMessage('');
      handleSelectGroupe(selectedGroupe);
    } catch (err) { console.error(err); }
  };

  const handleSendMessageAI = async () => {
    if (!question.trim() && !aiFileName) return;
    if (chatLoading) return;
    const userQuestion = question;
    const fileNote = aiFileName ? ` 📎 ${aiFileName}` : '';
    const fileToSend = aiFile;
    setChatLog(prev => [...prev, { role: 'user', text: userQuestion + fileNote }]);
    setQuestion('');
    setAiFile(null);
    setAiFileName('');
    setChatLoading(true);
    try {
        const res = await aiAPI.ask(userQuestion || 'Analyse ce document.', 'Délégué', fileToSend);
        setChatLog(prev => [...prev, { role: 'ai', text: res.data?.answer || res.data?.text || (typeof res.data === 'string' ? res.data : '❌ Réponse invalide.') }]);
    } catch (err) {
        setChatLog(prev => [...prev, { role: 'ai', text: "L'assistant RevisIA_H24 est momentanément saturé. Réessayez." }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleBroadcast = async (e) => {
    e.preventDefault();
    try {
        await academicAPI.broadcastAnnouncement({
            ...annonceForm,
            filiereId: user.filiere.id
        });
        showToast("Annonce diffusée à toute la classe !");
        setShowAnnonceModal(false);
        setAnnonceForm({ titre: '', message: '' });
    } catch (e) { showToast("Erreur lors de la diffusion.", "error"); }
  };

  const handleReportIssue = async (e) => {
    e.preventDefault();
    try {
        await academicAPI.reportIssue({
            auteur: user.nomComplet,
            message: issueForm.message
        });
        showToast("Problème remonté à l'administration.");
        setShowIssueModal(false);
        setIssueForm({ message: '' });
    } catch (e) { showToast("Erreur lors de l'opération.", "error"); }
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!file || !uploadData.matiereId) return;
    const formData = new FormData();
    formData.append('fichier', file);
    formData.append('identifiantPublic', uploadData.identifiant);
    formData.append('titre', uploadData.titre);
    formData.append('annee', uploadData.annee);
    formData.append('session', uploadData.session);
    formData.append('matiereId', uploadData.matiereId);

    try {
      if (uploadData.docType === 'COURS') {
        await coursAPI.publish(formData);
      } else {
        formData.append('typeAcces', 'GRATUIT');
        formData.append('prix', 0);
        await epreuveAPI.publish(formData);
      }
      setShowUploadModal(false);
      fetchData();
      showToast("Document partagé avec succès !");
    } catch (err) {
      showToast('❌ ' + (err?.response?.data?.error || 'Erreur lors de la publication.'), 'error');
    }
  };

  const handleSummarizeChat = async () => {
    if (messages.length === 0) { showToast("Aucun message à résumer.", "warning"); return; }
    
    const chatText = messages
        .filter(m => !m.isFlagged)
        .map(m => `${m.expediteur?.nomComplet}: ${m.contenu}`)
        .join("\n");
        
    const prompt = `Agis en tant que secrétaire académique. Fais un résumé concis des points importants de cette discussion de classe étudiante :\n\n${chatText}`;
    
    try {
        const res = await aiAPI.ask(prompt);
        const summaryText = res.data?.answer || res.data?.text || (typeof res.data === 'string' ? res.data : '❌ Réponse IA invalide.');
        showToast("✨ Résumé IA généré ! " + summaryText.substring(0, 80) + (summaryText.length > 80 ? '…' : ''));
    } catch (e) {
        showToast("L'IA est momentanément indisponible.", "error");
    }
  };

  return (
    <div className="elite-dashboard">
      {ToastUI}
      <AnimatedBackground variant="blue" intensity={0.4} />
      <MobileMenu />
      <aside className="elite-sidebar">
        <div className="brand-elite">
          <ShieldCheck color="#38BDF8" size={28} />
          <span>RevisIA_H24 <small>DÉLÉGUÉ</small></span>
        </div>
        <nav className="elite-nav">
          <button onClick={() => switchView('group')} className={view === 'group' ? 'active' : ''}><MessageSquare /> Mon Groupe</button>
          <button onClick={() => switchView('resources')} className={view === 'resources' ? 'active' : ''}><Layout /> Ressources</button>
          <button onClick={() => switchView('students')} className={view === 'students' ? 'active' : ''}><Users /> Étudiants</button>
          <button onClick={() => switchView('annonces')} className={view === 'annonces' ? 'active' : ''}><Megaphone /> Annonces</button>
        </nav>
        <div className="sidebar-footer">
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 10px',
            borderRadius: 12, cursor: 'pointer', marginBottom: 8, transition: 'background 0.2s',
            background: '#f8fafc', border: '1px solid #e2e8f0' }}
            onClick={() => setShowProfile(true)}
            onMouseEnter={e => e.currentTarget.style.background = 'rgba(14,165,233,0.07)'}
            onMouseLeave={e => e.currentTarget.style.background = '#f8fafc'}>
            <div style={{ width: 32, height: 32, borderRadius: '50%', background: 'rgba(56,189,248,0.2)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontWeight: 800, color: '#38BDF8', fontSize: '0.85rem', overflow: 'hidden', flexShrink: 0 }}>
              {user?.photoUrl
                ? <img src={user.photoUrl} alt="avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                : user?.nomComplet?.charAt(0)
              }
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <p style={{ color: '#0f172a', fontWeight: 700, fontSize: '0.76rem', margin: 0,
                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{user?.nomComplet}</p>
              <p style={{ color: '#475569', fontSize: '0.66rem', margin: 0 }}>Mon profil</p>
            </div>
          </div>
          <button onClick={() => setShowIssueModal(true)} className="btn-report"><AlertTriangle size={16} /> Un problème ?</button>
          <button onClick={() => setShowLogoutConfirm(true)} className="btn-logout"><LogOut size={16} /> Se déconnecter</button>
        </div>
      </aside>

      <main className="elite-main" style={{ position: 'relative', zIndex: 1 }}>
        <header className="elite-header">
          <div>
            <h1>Espace <span className="text-glow">Délégué</span></h1>
            <p>{user?.filiere?.nom || 'Votre Promotion'} — {user?.universite?.sigle || 'Université'}</p>
          </div>
          <div className="header-actions">
            <button onClick={() => setShowAnnonceModal(true)} className="btn-gold"><Megaphone /> Diffuser Annonce</button>
            <div className="notif-wrapper">
                <button onClick={() => setShowNotifList(!showNotifList)} className="btn-icon">
                    <Bell />
                    {notifications.filter(n => !n.isRead).length > 0 && <span className="notif-badge"></span>}
                </button>
                {/* ... dropdown notifications (même code que précédemment) */}
            </div>
          </div>
        </header>

        {canGoBack && (
          <DashboardBackButton
            label={`Retour — ${getBackLabel(DELEGATE_VIEW_LABELS)}`}
            onBack={goBack}
          />
        )}

        {view === 'annonces' && (
           <div className="view-container">
             <div className="view-header">
               <h2>Fil d'Annonces de la Promotion</h2>
               <p>Ici s'affichent les communications officielles que vous diffusez.</p>
             </div>
             <div className="annonces-list">
                {notifications.filter(n => n.titre.includes("Annonce Délégué")).map(n => (
                    <div key={n.id} className="elite-card announcement">
                        <div className="card-icon"><Megaphone /></div>
                        <div className="card-data">
                            <h4>{n.titre}</h4>
                            <p>{n.message}</p>
                            <small>{new Date(n.dateCreation).toLocaleString()}</small>
                        </div>
                    </div>
                ))}
                {notifications.filter(n => n.titre.includes("Annonce Délégué")).length === 0 && (
                    <div className="empty-state">Aucune annonce diffusée récemment.</div>
                )}
             </div>
           </div>
        )}

        {view === 'group' && (
          <div className="messaging-container-elite">
            {/* ... chat area ... */}
            <div className="chat-area-elite">
                <div className="chat-header-lite" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3>Discussion de Filière : {selectedGroupe?.nom}</h3>
                    <button onClick={handleSummarizeChat} className="btn-small-outline" style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <Sparkles size={14} color="#F97316" /> Résumer le débat (IA)
                    </button>
                </div>
                <div className="chat-messages-elite">
                    {messages.map(m => (
                        <div key={m.id} className={`msg-elite ${m.expediteur?.id === user?.id ? 'sent' : 'received'} ${m.isFlagged ? 'msg-flagged' : ''}`}>
                            <div className="msg-sender">{m.expediteur?.nomComplet}</div>
                            <div className="msg-content">
                                {m.isFlagged ? (
                                    <span style={{ color: '#ef4444', fontStyle: 'italic' }}>
                                        {m.contenu}
                                    </span>
                                ) : (
                                    m.contenu
                                )}
                            </div>
                        </div>
                    ))}
                </div>
                <form onSubmit={handleSendMessage} className="chat-input-elite">
                    <input type="text" placeholder="Envoyer un message à la classe..." value={newMessage} onChange={e => setNewMessage(e.target.value)} />
                    <button type="submit"><Send /></button>
                </form>
            </div>
          </div>
        )}

        {view === 'students' && (
          <div className="view-container">
             <div className="view-header">
               <h2>Membres de la Promotion</h2>
               <div className="participation-stats">
                  <div className="stat-pill"><Users size={14}/> {selectedGroupe?.membres?.length || groupes.length || 0} Étudiants</div>
                  <div className="stat-pill"><CheckCircle size={14}/> Promotion active</div>
               </div>
             </div>
             <div className="table-elite-container">
               <table className="table-elite">
                 <thead><tr><th>Nom Complet</th><th>Rôle</th><th>Activité</th><th>Action</th></tr></thead>
                 <tbody>
                    <tr className="row-premium">
                        <td>Jean Dupont</td>
                        <td><span className="role-badge ETUDIANT">ÉTUDIANT</span></td>
                        <td><div className="activity-bar"><div className="fill" style={{width: '75%'}}></div></div></td>
                        <td><button className="btn-small-outline">Détails</button></td>
                    </tr>
                    <tr className="row-premium">
                        <td>Alice Vasseur</td>
                        <td><span className="role-badge ETUDIANT">ÉTUDIANT</span></td>
                        <td><div className="activity-bar"><div className="fill" style={{width: '90%'}}></div></div></td>
                        <td><button className="btn-small-outline">Détails</button></td>
                    </tr>
                 </tbody>
               </table>
             </div>
          </div>
        )}

        {view === 'resources' && (
           <div className="view-container">
             <div className="view-header">
               <h2>Ressources de la Classe</h2>
               <button onClick={() => setShowUploadModal(true)} className="btn-gold"><Plus /> Partager un document</button>
             </div>
             <div className="grid-resources">
                {epreuves.filter(e => e.matiere?.filiere?.id === user?.filiere?.id).map(e => (
                    <div key={e.id} className="elite-card resource">
                        <FileText size={40} color="var(--primary)" />
                        <h4>{e.titre}</h4>
                        <p>{e.matiere?.nom}</p>
                        <div className="card-footer">
                            <span>{e.annee}</span>
                            <button className="btn-small-gold">Consulter</button>
                        </div>
                    </div>
                ))}
             </div>
           </div>
        )}

        {/* FLOATING AI */}
        <div onClick={() => setShowChat(true)} className="iq-chat-trigger">
          <BrainCircuit size={32} />
        </div>

        <AnimatePresence>
          {showAnnonceModal && (
            <div className="elite-modal-overlay">
              <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="elite-modal">
                <div className="modal-header"><h3>Diffuser une Annonce</h3><X onClick={() => setShowAnnonceModal(false)} /></div>
                <form onSubmit={handleBroadcast}>
                  <input type="text" placeholder="Titre de l'annonce" required onChange={e => setAnnonceForm({...annonceForm, titre: e.target.value})} />
                  <textarea placeholder="Votre message à toute la classe..." rows={6} required onChange={e => setAnnonceForm({...annonceForm, message: e.target.value})}></textarea>
                  <button type="submit" className="btn-gold-full">Diffuser maintenant</button>
                </form>
              </motion.div>
            </div>
          )}

          {showIssueModal && (
            <div className="elite-modal-overlay">
              <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="elite-modal">
                <div className="modal-header"><h3>Signaler un problème</h3><X onClick={() => setShowIssueModal(false)} /></div>
                <form onSubmit={handleReportIssue}>
                  <p>Décrivez le problème. Il sera envoyé directement aux administrateurs de l'université.</p>
                  <textarea placeholder="Ex: Problème d'accès au document MTH101, étudiant bloqué..." rows={5} required onChange={e => setIssueForm({message: e.target.value})}></textarea>
                  <button type="submit" className="btn-gold-full" style={{ background: '#EF4444' }}>Envoyer l'alerte</button>
                </form>
              </motion.div>
            </div>
          )}

          {showUploadModal && (
             <div className="elite-modal-overlay">
                <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="elite-modal">
                    <div className="modal-header"><h3>Partager une Ressource</h3><X onClick={() => setShowUploadModal(false)} /></div>
                    <form onSubmit={handleUpload}>
                        <select required value={uploadData.docType || 'EPREUVE'} onChange={e => setUploadData({...uploadData, docType: e.target.value})} style={{ width: '100%', padding: '12px', borderRadius: '10px', background: '#f1f5f9', color: '#0c1730', border: '1px solid #e2e8f0', marginBottom: '15px' }}>
                            <option value="EPREUVE" style={{ background: '#f8fafc' }}>Épreuve d'Examen</option>
                            <option value="COURS" style={{ background: '#f8fafc' }}>Cours / TD / TP</option>
                        </select>
                        <input type="text" placeholder="Code Unique (Ex: MTH101-TD1)" required onChange={e => setUploadData({...uploadData, identifiant: e.target.value})} />
                        <input type="text" placeholder="Titre (Ex: Cours d'Algèbre)" required onChange={e => setUploadData({...uploadData, titre: e.target.value})} />
                        <select required onChange={e => setUploadData({...uploadData, matiereId: e.target.value})}>
                            <option value="">-- Choisir la Matière --</option>
                            {matieres.filter(m => m.filiere?.id === user?.filiere?.id).map(m => <option key={m.id} value={m.id}>{m.nom}</option>)}
                        </select>
                        <input type="file" required onChange={e => setFile(e.target.files[0])} />
                        <button type="submit" className="btn-gold-full">Publier</button>
                    </form>
                </motion.div>
             </div>
          )}

          {showChat && (
            <div className="elite-modal-overlay">
              <motion.div initial={{ y: 100 }} animate={{ y: 0 }} className="chat-window-elite">
                <div className="chat-header"><h3>🤖 Assistant RevisIA_H24</h3><X onClick={() => setShowChat(false)} /></div>
                <div className="chat-body">
                  {chatLog.map((c, i) => (
                    <div key={i} className={`msg ${c.role}`} style={{ whiteSpace: 'pre-wrap' }}>
                      {c.imageUrl && <img src={c.imageUrl} alt="pièce jointe" style={{ maxWidth: '100%', borderRadius: '8px', marginBottom: '6px', display: 'block' }} />}
                      {c.text}
                    </div>
                  ))}
                  {chatLoading && <div className="msg ai" style={{ opacity: 0.6 }}>⏳ RevisIA_H24 réfléchit...</div>}
                </div>

                {/* Aperçu du fichier attaché */}
                {aiFileName && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '6px 12px', background: 'rgba(56,189,248,0.1)', borderTop: '1px solid rgba(56,189,248,0.2)', fontSize: '0.8rem', color: '#38BDF8' }}>
                    <Paperclip size={13} />
                    <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{aiFileName}</span>
                    <button onClick={() => { setAiFile(null); setAiFileName(''); }} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#EF4444', padding: 0 }}><X size={14} /></button>
                  </div>
                )}

                {/* Inputs fichiers cachés */}
                <input ref={aiFileInputRef} type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.png,.jpg,.jpeg,.webp,.gif" style={{ display: 'none' }} onChange={handleAiFileChange} />
                <input ref={aiCameraInputRef} type="file" accept="image/*" capture="environment" style={{ display: 'none' }} onChange={handleAiFileChange} />

                <div className="chat-input-area" style={{ display: 'flex', alignItems: 'center', gap: '6px', padding: '10px 12px' }}>
                  {/* Bouton Fichier */}
                  <button
                    onClick={() => aiFileInputRef.current?.click()}
                    title="Joindre un fichier ou une image"
                    style={{ background: aiFileName ? 'rgba(56,189,248,0.2)' : '#f1f5f9', border: '1px solid #e2e8f0', cursor: 'pointer', color: aiFileName ? '#0ea5e9' : '#64748b', width: '36px', height: '36px', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
                  ><Paperclip size={17} /></button>

                  {/* Bouton Caméra (photo directe téléphone) */}
                  <button
                    onClick={() => aiCameraInputRef.current?.click()}
                    title="Prendre une photo avec l'appareil photo"
                    style={{ background: '#f1f5f9', border: 'none', cursor: 'pointer', color: '#475569', width: '36px', height: '36px', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
                  ><Camera size={17} /></button>

                  <input
                    type="text"
                    placeholder="Une question ? Envoyez un fichier ou une photo…"
                    value={question}
                    onChange={e => setQuestion(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') handleSendMessageAI(); }}
                    style={{ flex: 1, background: 'transparent', border: 'none', outline: 'none', color: '#0c1730', fontSize: '0.9rem' }}
                  />
                  <button
                    onClick={handleSendMessageAI}
                    disabled={chatLoading || (!question.trim() && !aiFileName)}
                    style={{ background: (chatLoading || (!question.trim() && !aiFileName)) ? '#334155' : 'linear-gradient(135deg,#6366F1,#8B5CF6)', border: 'none', borderRadius: '50%', width: '36px', height: '36px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: 'white', flexShrink: 0 }}
                  ><Send size={16} /></button>
                </div>
              </motion.div>
            </div>
          )}

        </AnimatePresence>
      </main>
      <FloatingAIAssistant user={user} />
      <AnimatePresence>
        {showProfile && user && (
          <ProfileModal user={user} onClose={() => setShowProfile(false)}
            onSaved={(u) => setUser(p => ({ ...p, ...u }))} />
        )}
      </AnimatePresence>
      <AssistanceWidget universiteId={user?.universite?.id} />
      <LogoutConfirmModal isOpen={showLogoutConfirm} onClose={() => setShowLogoutConfirm(false)} />
    </div>
  );
};

export default DelegateDashboard;


