import React from 'react';
import { ArrowLeft } from 'lucide-react';

/**
 * DashboardBackButton — Bouton retour style WhatsApp.
 *
 * Desktop : bouton pill inline dans le contenu.
 * Mobile  : barre pleine largeur sticky en haut, fond glass, bord-à-bord.
 *
 * Props:
 *   label   — texte affiché (ex: "Bibliothèque")
 *   onBack  — callback retour
 *   variant — 'light' | 'dark' | 'ghost' (desktop uniquement)
 *   style   — override style inline
 */
const DashboardBackButton = ({
  label = 'Retour',
  onBack,
  variant = 'light',
  style = {},
  className = '',
}) => {
  return (
    <button
      type="button"
      onClick={onBack}
      className={`dashboard-back-button dbb-variant-${variant} ${className}`.trim()}
      style={style}
      aria-label={`Retour : ${label}`}
    >
      <span className="dbb-icon">
        <ArrowLeft size={20} strokeWidth={2.5} />
      </span>
      <span className="dbb-label">{label}</span>
    </button>
  );
};

export default DashboardBackButton;
